pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount < type(uint256).max / 2);
        // only the owner may pass the require check
        vm.assume(actor == address(this));
        // adversarial counterparty: a receiver that always reverts
        Reverter r = new Reverter();
        vm.deal(address(this), amount);
        bool ok;
        try c.sendTo(address(r), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: sending to a receiver that refuses funds must always revert.
        assertTrue(!ok, "sendTo to a reverting receiver must revert");
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

