pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker atk;

    function setUp() public {
        c = new C();
        atk = new Attacker();
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.deal(address(this), amount);
        (bool s, ) = address(c).call{value: amount}("");
        require(s);

        atk.reset();
        vm.prank(actor);
        try c.sendTo(address(atk), amount) {
            // owner call: transfer happened legitimately
        } catch {
            // non-owner: entire call reverts in both versions
        }
        // Rule: a non-owner caller must never observe funds credited to it
        // during sendTo (check happens before effects). The mutant credits
        // the receiver and only then runs require(), so the re-entrant
        // attacker sees its balance increase before the revert.
        assertTrue(!atk.sawFunds());
    }
}

contract Attacker {
    bool public sawFunds;
    uint256 private before;

    function reset() external { sawFunds = false; }

    receive() external payable {
        sawFunds = (address(this).balance > before);
        // re-enter to confirm the ownership check has not yet run
        (bool ok, ) = address(msg.sender).call(abi.encodeWithSignature("sendTo(address,uint256)", address(this), 0));
        ok; // ignore result
    }

    function probe(C target) external {
        before = address(this).balance;
        (bool s, ) = address(target).call(abi.encodeWithSignature("sendTo(address,uint256)", address(this), 1));
        require(s);
    }
}

// Attacker used as re-entrant receiver; probe() kept for direct driving.
contract Driver is Attacker {}

