import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address receiver, uint96 amount) public {
        // Admissible domain: any caller except the deployer (this test contract), which is
        // the only address the constructor accepted as owner. Keep the domain wide: any
        // receiver, any amount (funded below so balance is never the limiting factor).
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        vm.deal(address(c), uint256(amount));

        vm.prank(actor);
        bool ok;
        try c.sendTo(receiver, uint256(amount)) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for EVERY admissible input (any non-owner caller, any receiver,
        // any amount), the boundary call to sendTo must revert. The reference contract
        // checks ownership before anything else, so this holds for all inputs. The mutant
        // moves the ownership check after the transfer, so on this call boundary the
        // revert/completion behavior is no longer owner-gated as required.
        assertTrue(!ok, "sendTo by a non-owner caller must revert");
    }
}

