pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 constant SEED = 2 ** 128;

    function setUp() public {
        c = new C();
        vm.deal(address(c), SEED);
    }

    function testFuzz_property(address attackerOwner, uint256 amount) public {
        vm.assume(attackerOwner != address(this));
        vm.assume(attackerOwner != address(c));
        amount = bound(amount, 1, SEED / 4);

        ReentrantReceiver r = new ReentrantReceiver(c, amount);

        // owner (deployer) funded attacker so it can act as a caller; caller is NOT the owner
        vm.deal(attackerOwner, 1 ether);
        vm.prank(attackerOwner);
        try c.sendTo(address(r), amount) {
            // reference reverts here for non-owner; if it somehow succeeds, balance must still hold
        } catch {}

        // RULE: a non-owner sendTo call must never change the contract's balance —
        // the ownership check runs BEFORE any transfer. The mutant transfers first,
        // and the re-entrant receiver drains funds (twice) before the outer call reverts.
        assertTrue(address(c).balance == SEED);
    }
}

contract ReentrantReceiver {
    C c;
    uint256 amt;
    bool reentered;

    constructor(C _c, uint256 _amt) {
        c = _c;
        amt = _amt;
    }

    fallback() external payable {
        if (!reentered) {
            reentered = true;
            try c.sendTo(address(this), amt) {} catch {}
        }
    }

    receive() external payable {
        this.fallback();
    }
}

