pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface CSender {
    function sendTo(address receiver, uint amount) external;
}

contract InvMutTest is Test {
    C c;
    Attacker atk;

    function setUp() public {
        c = new C();
        atk = new Attacker(address(c));
        vm.deal(address(c), 1 ether);
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, 1 ether - 1); // transfer must succeed and leave >= 1 wei for reentrancy
        atk.reset();
        c.sendTo(address(atk), amount); // owner (this contract) approves the send
        // Rule: exactly `amount` is delivered; ownership check precedes transfer, so no reentrant extra transfer occurs.
        assertTrue(address(atk).balance == amount, "receiver must get exactly amount");
    }
}

contract Attacker {
    CSender c;
    bool attacked;

    constructor(address _c) {
        c = CSender(_c);
    }

    function reset() external {
        attacked = false;
    }

    receive() external payable {
        if (!attacked) {
            attacked = true;
            // re-enter sendTo; in the correct contract the ownership check reverts this before any transfer
            (bool ok, ) = address(c).call(
                abi.encodeWithSignature("sendTo(address,uint256)", address(this), address(c).balance)
            );
            ok; // ignore result
        }
    }
}

